"""Domain schemas.

Two kinds of claims are kept strictly apart:

* ``Evidence`` — a verbatim span of extracted page text, located by document,
  page and character offsets. Never produced by a model.
* ``Inference`` — a statement generated by a model. It must cite at least one
  ``Evidence`` and records which model produced it.

IDs are deterministic (see ``app.core.ids``). Each model derives its expected
ID from its own content: an omitted ID is filled in, a mismatching one is
rejected, so callers cannot attach a fabricated identifier to a record.
"""

from datetime import date, datetime
from enum import StrEnum
from typing import Literal, Self

from pydantic import BaseModel, ConfigDict, Field, HttpUrl, model_validator

from app.core import ids


class _Schema(BaseModel):
    model_config = ConfigDict(extra="forbid", str_strip_whitespace=False)

    def _bind_id(self, field: str, expected: str) -> None:
        current = getattr(self, field)
        if not current:
            object.__setattr__(self, field, expected)
        elif current != expected:
            raise ValueError(f"{field} {current!r} does not match content-derived id {expected!r}")


class Document(_Schema):
    document_id: str = ""
    sha256: str = Field(pattern=r"^[0-9a-f]{64}$")
    filename: str = Field(min_length=1)
    title: str | None = None
    page_count: int = Field(ge=1)
    issuer: str = "Banque Centrale de Tunisie"
    reference: str | None = Field(default=None, description="Official reference, e.g. 'Circulaire n°2018-06'.")
    publication_date: date | None = None
    source_url: HttpUrl | None = None

    @model_validator(mode="after")
    def _check_id(self) -> Self:
        self._bind_id("document_id", ids.document_id(self.sha256))
        return self


class ExtractedPage(_Schema):
    """Raw text of one PDF page. Evidence offsets index into ``text``."""

    page_id: str = ""
    document_id: str
    page_number: int = Field(ge=1, description="1-based physical page number in the PDF.")
    text: str

    @property
    def has_text(self) -> bool:
        return bool(self.text.strip())

    @model_validator(mode="after")
    def _check_id(self) -> Self:
        self._bind_id("page_id", ids.page_id(self.document_id, self.page_number))
        return self


class ExtractedDocument(_Schema):
    document: Document
    pages: list[ExtractedPage]

    @model_validator(mode="after")
    def _check_pages(self) -> Self:
        if [p.page_number for p in self.pages] != list(range(1, self.document.page_count + 1)):
            raise ValueError("pages must be numbered 1..page_count in order")
        if any(p.document_id != self.document.document_id for p in self.pages):
            raise ValueError("every page must belong to the document")
        return self


class Evidence(_Schema):
    """A verified, verbatim quote: ``page.text[char_start:char_end] == quote``."""

    kind: Literal["verified_extract"] = "verified_extract"
    evidence_id: str = ""
    document_id: str
    page_number: int = Field(ge=1)
    char_start: int = Field(ge=0)
    char_end: int = Field(gt=0)
    quote: str = Field(min_length=1)

    @model_validator(mode="after")
    def _check(self) -> Self:
        if not self.quote.strip():
            raise ValueError("quote must contain non-whitespace text")
        if self.char_end - self.char_start != len(self.quote):
            raise ValueError("char_end - char_start must equal len(quote)")
        self._bind_id(
            "evidence_id",
            ids.stable_id(
                "ev", self.document_id, self.page_number, self.char_start, self.char_end,
                ids.sha256_hex(self.quote.encode("utf-8")),
            ),
        )
        return self


class Provision(_Schema):
    provision_id: str = ""
    document_id: str
    label: str = Field(min_length=1, description="Provision label as printed, e.g. 'Article 5'.")
    text: str = Field(min_length=1)
    page_start: int = Field(ge=1)
    page_end: int = Field(ge=1)

    @model_validator(mode="after")
    def _check(self) -> Self:
        if self.page_end < self.page_start:
            raise ValueError("page_end must be >= page_start")
        self._bind_id("provision_id", ids.stable_id("prov", self.document_id, self.label, self.page_start))
        return self


class Inference(_Schema):
    """A model-generated statement. Never treated as evidence."""

    kind: Literal["model_inference"] = "model_inference"
    inference_id: str = ""
    statement: str = Field(min_length=1)
    model_id: str = Field(min_length=1, description="Identifier of the model that produced the statement.")
    supporting_evidence_ids: list[str] = Field(min_length=1)

    @model_validator(mode="after")
    def _check(self) -> Self:
        _unique(self.supporting_evidence_ids, "supporting_evidence_ids")
        self._bind_id(
            "inference_id",
            ids.stable_id("inf", self.model_id, self.statement, *sorted(self.supporting_evidence_ids)),
        )
        return self


class RelationType(StrEnum):
    AMENDS = "amends"
    REPEALS = "repeals"
    SUPERSEDES = "supersedes"
    REFERENCES = "references"
    IMPLEMENTS = "implements"
    CONFLICTS_WITH = "conflicts_with"


class RegulatoryRelationship(_Schema):
    """A directed relation between two provisions.

    ``basis="extracted"``: stated explicitly in the source text (deterministic).
    ``basis="inferred"``: proposed by a model; must reference an ``Inference``.
    Both require verified evidence.
    """

    relationship_id: str = ""
    source_provision_id: str
    target_provision_id: str
    relation_type: RelationType
    basis: Literal["extracted", "inferred"]
    evidence_ids: list[str] = Field(min_length=1)
    inference_id: str | None = None

    @model_validator(mode="after")
    def _check(self) -> Self:
        if self.source_provision_id == self.target_provision_id:
            raise ValueError("a provision cannot relate to itself")
        _unique(self.evidence_ids, "evidence_ids")
        if self.basis == "inferred" and self.inference_id is None:
            raise ValueError("inferred relationships must reference an inference_id")
        if self.basis == "extracted" and self.inference_id is not None:
            raise ValueError("extracted relationships must not reference an inference")
        self._bind_id(
            "relationship_id",
            ids.stable_id("rel", self.source_provision_id, self.relation_type.value, self.target_provision_id),
        )
        return self


class InvestigationReport(_Schema):
    """Self-contained report: every referenced ID must resolve inside the report."""

    report_id: str = ""
    question: str = Field(min_length=1)
    generated_at: datetime
    document_ids: list[str] = Field(min_length=1)
    provisions: list[Provision] = Field(default_factory=list)
    evidence: list[Evidence] = Field(default_factory=list)
    inferences: list[Inference] = Field(default_factory=list)
    relationships: list[RegulatoryRelationship] = Field(default_factory=list)

    @model_validator(mode="after")
    def _check_references(self) -> Self:
        docs = _unique(self.document_ids, "document_ids")
        provs = _unique([p.provision_id for p in self.provisions], "provisions")
        evs = _unique([e.evidence_id for e in self.evidence], "evidence")
        infs = _unique([i.inference_id for i in self.inferences], "inferences")
        _unique([r.relationship_id for r in self.relationships], "relationships")

        for item in [*self.provisions, *self.evidence]:
            _require(item.document_id, docs, "document")
        for inf in self.inferences:
            for ev_id in inf.supporting_evidence_ids:
                _require(ev_id, evs, "evidence")
        for rel in self.relationships:
            _require(rel.source_provision_id, provs, "provision")
            _require(rel.target_provision_id, provs, "provision")
            for ev_id in rel.evidence_ids:
                _require(ev_id, evs, "evidence")
            if rel.inference_id is not None:
                _require(rel.inference_id, infs, "inference")

        self._bind_id(
            "report_id",
            ids.stable_id("rep", self.question, self.generated_at.isoformat(), *sorted(self.document_ids)),
        )
        return self


def _unique(values: list[str], name: str) -> set[str]:
    seen = set(values)
    if len(seen) != len(values):
        raise ValueError(f"duplicate ids in {name}")
    return seen


def _require(ref: str, known: set[str], kind: str) -> None:
    if ref not in known:
        raise ValueError(f"unresolved {kind} reference {ref!r}")
